INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9801, 'តើរូបមន្តសម្រាប់គណនាមាត្រដ្ឋាន \(E\) ធៀបរវាងប្រវែងលើប្លង់ \(d\) និងប្រវែងពិត \(D\) (ក្នុងខ្នាតដូចគ្នា) ណាត្រឹមត្រូវ?', NULL, '["\\(E = \\dfrac{D}{d}\\)", "\\(E = \\dfrac{d}{D}\\)", "\\(E = d \\times D\\)", "\\(E = D - d\\)"]', 1, NULL, 1, 'mcq', 'មាត្រដ្ឋានស្មើផលធៀបរវាងប្រវែងលើប្លង់និងប្រវែងពិតជាក់ស្តែង ៖ \(E = \dfrac{d}{D}\)', 'មាត្រដ្ឋាន', 'easy', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g8-b1a9362c1c.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9802, 'ប្លង់មួយមានមាត្រដ្ឋាន \(1/100\) (\(1 : 100\))។ តើប្រវែង \(1\ \text{cm}\) នៅលើប្លង់តំណាងឱ្យប្រវែងពិតប៉ុន្មាន?', 'g8-b1a9362c1c.svg', '["\\(100\\ \\text{cm} = 1\\ \\text{m}\\)", "\\(100\\ \\text{m}\\)", "\\(10\\ \\text{cm}\\)", "\\(10\\ \\text{m}\\)"]', 0, NULL, 1, 'mcq', 'មាត្រដ្ឋាន \(1/100\) មានន័យថា \(1\ \text{cm}\) លើប្លង់ស្មើ \(100\ \text{cm} = 1\ \text{m}\) ជាក់ស្តែង', 'មាត្រដ្ឋាន', 'easy', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9803, 'នៅលើផែនទីប្រទេសកម្ពុជាមួយមានមាត្រដ្ឋាន \(1/1\,000\,000\)។ តើប្រវែង \(1\ \text{cm}\) លើផែនទីស្មើនឹងប្រវែងពិតប៉ុន្មានគីឡូម៉ែត្រ?', NULL, '["\\(0.1\\ \\text{km}\\)", "\\(100\\ \\text{km}\\)", "\\(10\\ \\text{km}\\)", "\\(1\\ \\text{km}\\)"]', 2, NULL, 1, 'mcq', '\(1\,000\,000\ \text{cm} = 10\,000\ \text{m} = 10\ \text{km}\)', 'មាត្រដ្ឋាន', 'easy', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9804, 'នៅលើប្លង់មាត្រដ្ឋាន \(1/500\) ចម្ងាយរវាងចំណុចពីរគឺ \(4\ \text{cm}\)។ គណនាចម្ងាយពិតជាក់ស្តែងគិតជាម៉ែត្រ។', NULL, '["\\(200\\ \\text{m}\\)", "\\(2\\,000\\ \\text{m}\\)", "\\(20\\ \\text{m}\\)", "\\(2\\ \\text{m}\\)"]', 2, NULL, 1, 'mcq', '\(D = 4 \times 500 = 2\,000\ \text{cm} = 20\ \text{m}\)', 'មាត្រដ្ឋាន', 'easy', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9805, 'ផ្លូវមួយមានប្រវែងពិត \(50\ \text{m}\) (\(5\,000\ \text{cm}\))។ តើនៅលើប្លង់មាត្រដ្ឋាន \(1/1\,000\) ផ្លូវនោះមានប្រវែងប៉ុន្មាន?', NULL, '["\\(0.5\\ \\text{cm}\\)", "\\(50\\ \\text{cm}\\)", "\\(500\\ \\text{cm}\\)", "\\(5\\ \\text{cm}\\)"]', 3, NULL, 1, 'mcq', '\(d = \dfrac{5\,000}{1\,000} = 5\ \text{cm}\)', 'មាត្រដ្ឋាន', 'easy', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g8-1e94160b54.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9806, 'បន្ទាត់ដែលមានខ្នាតបែងចែកជាចន្លោះស្មើៗគ្នា ដើម្បីបង្ហាញពីចម្ងាយពិតនៅលើផែនទី ហៅថាអ្វី?', 'g8-1e94160b54.svg', '["បន្ទាត់សញ្ញា", "បន្ទាត់ត្រង់", "បន្ទាត់កែង", "មាត្រដ្ឋានជាបន្ទាត់ (Graphic Scale Bar)"]', 3, NULL, 1, 'mcq', 'មាត្រដ្ឋានជាបន្ទាត់ គឺជាគំនូសបន្ទាត់ចែកជាកង់ៗសម្រាប់តាងប្រវែងជាក់ស្តែង', 'មាត្រដ្ឋាន', 'easy', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9807, 'តើប្រវែង \(1\ \text{km}\) ស្មើនឹងប៉ុន្មានសង់ទីម៉ែត្រ (\(\text{cm}\))?', NULL, '["\\(1\\,000\\,000\\ \\text{cm}\\)", "\\(10\\,000\\ \\text{cm}\\)", "\\(100\\,000\\ \\text{cm}\\)", "\\(1\\,000\\ \\text{cm}\\)"]', 2, NULL, 1, 'mcq', '\(1\ \text{km} = 1\,000\ \text{m} = 100\,000\ \text{cm}\)', 'មាត្រដ្ឋាន', 'easy', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9808, 'តើមាត្រដ្ឋានណាខាងក្រោមជាមាត្រដ្ឋានបង្រួម (Reduction Scale)?', NULL, '["\\(10 : 1\\)", "\\(1 : 50\\)", "\\(2 : 1\\)", "\\(5 : 1\\)"]', 1, NULL, 1, 'mcq', 'មាត្រដ្ឋានដែលមានភាគយកតូចជាងភាគបែង (\(E < 1\)) គឺជាមាត្រដ្ឋានបង្រួម', 'មាត្រដ្ឋាន', 'easy', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9809, 'ដើម្បីគូសប្លង់គ្រឿងបន្លាស់នាឡិកាតូចមួយឱ្យធំច្បាស់ តើគេត្រូវប្រើប្រភេទមាត្រដ្ឋានណា?', NULL, '["មាត្រដ្ឋានធម្មតា", "មាត្រដ្ឋានបង្រួម", "មាត្រដ្ឋានសូន្យ", "មាត្រដ្ឋានពង្រីក (Enlargement Scale)"]', 3, NULL, 1, 'mcq', 'សម្រាប់វត្ថុតូចៗ គេត្រូវប្រើមាត្រដ្ឋានពង្រីក (ឧ. \(5:1\) ឬ \(10:1\))', 'មាត្រដ្ឋាន', 'easy', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9810, 'ប្រវែងលើប្លង់គឺ \(2\ \text{cm}\) ហើយប្រវែងពិតគឺ \(10\ \text{m}\) (\(1\,000\ \text{cm}\))។ គណនាមាត្រដ្ឋាន។', NULL, '["\\(\\dfrac{1}{5}\\)", "\\(\\dfrac{1}{5\\,000}\\)", "\\(\\dfrac{1}{500}\\)", "\\(\\dfrac{1}{50}\\)"]', 2, NULL, 1, 'mcq', '\(E = \dfrac{2}{1\,000} = \dfrac{1}{500}\)', 'មាត្រដ្ឋាន', 'easy', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9811, 'នៅលើផែនទីមាត្រដ្ឋាន \(1/50\,000\) ចម្ងាយរវាងភូមិពីរវាស់បាន \(6\ \text{cm}\)។ គណនាចម្ងាយពិតគិតជាគីឡូម៉ែត្រ។', NULL, '["\\(30\\ \\text{km}\\)", "\\(0.3\\ \\text{km}\\)", "\\(3\\ \\text{km}\\)", "\\(300\\ \\text{km}\\)"]', 2, NULL, 2, 'mcq', '\(D = 6 \times 50\,000 = 300\,000\ \text{cm} = 3\,000\ \text{m} = 3\ \text{km}\)', 'មាត្រដ្ឋាន', 'medium', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9812, 'ចម្ងាយពិតរវាងក្រុងពីរគឺ \(45\ \text{km}\)។ នៅលើផែនទីមាត្រដ្ឋាន \(1/250\,000\) តើចម្ងាយនេះតាងដោយប្រវែងប៉ុន្មាន?', NULL, '["\\(180\\ \\text{cm}\\)", "\\(9\\ \\text{cm}\\)", "\\(1.8\\ \\text{cm}\\)", "\\(18\\ \\text{cm}\\)"]', 3, NULL, 2, 'mcq', '\(D = 45\ \text{km} = 4\,500\,000\ \text{cm} \Rightarrow d = \dfrac{4\,500\,000}{250\,000} = 18\ \text{cm}\)', 'មាត្រដ្ឋាន', 'medium', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9813, 'ចម្ងាយពិតរវាងទីក្រុងពីរគឺ \(120\ \text{km}\) ហើយនៅលើផែនទីវាស់បាន \(6\ \text{cm}\)។ គណនាមាត្រដ្ឋាននៃផែនទី។', NULL, '["\\(\\dfrac{1}{2\\,000\\,000}\\)", "\\(\\dfrac{1}{200\\,000}\\)", "\\(\\dfrac{1}{1\\,200\\,000}\\)", "\\(\\dfrac{1}{20\\,000}\\)"]', 0, NULL, 2, 'mcq', '\(D = 120\ \text{km} = 12\,000\,000\ \text{cm} \Rightarrow E = \dfrac{6}{12\,000\,000} = \dfrac{1}{2\,000\,000}\)', 'មាត្រដ្ឋាន', 'medium', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9814, 'បើប្លង់មួយមានមាត្រដ្ឋានប្រវែង \(E = \dfrac{1}{100}\) តើផលធៀបផ្ទៃក្រឡាលើប្លង់ធៀបនឹងផ្ទៃក្រឡាពិតស្មើនឹងប៉ុន្មាន?', NULL, '["\\(\\dfrac{1}{1\\,000}\\)", "\\(\\dfrac{1}{100}\\)", "\\(\\dfrac{1}{200}\\)", "\\(\\dfrac{1}{10\\,000}\\)"]', 3, NULL, 2, 'mcq', 'ផលធៀបផ្ទៃក្រឡាស្មើការេនៃមាត្រដ្ឋានប្រវែង ៖ \(E^2 = \left(\dfrac{1}{100}\right)^2 = \dfrac{1}{10\,000}\)', 'មាត្រដ្ឋាន', 'medium', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9815, 'នៅលើប្លង់មាត្រដ្ឋាន \(1/100\) បន្ទប់មួយមានបណ្តោយ \(5\ \text{cm}\) និងទទឹង \(4\ \text{cm}\)។ គណនាផ្ទៃក្រឡាពិតនៃបន្ទប់នោះជាម៉ែត្រការេ។', NULL, '["\\(2\\ \\text{m}^2\\)", "\\(20\\,000\\ \\text{m}^2\\)", "\\(20\\ \\text{m}^2\\)", "\\(200\\ \\text{m}^2\\)"]', 2, NULL, 2, 'mcq', 'បណ្តោយពិត \(5\ \text{m}\), ទទឹងពិត \(4\ \text{m} \Rightarrow S = 5 \times 4 = 20\ \text{m}^2\)', 'មាត្រដ្ឋាន', 'medium', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9816, 'ដីស្រែមួយកន្លែងមានផ្ទៃពិត \(800\ \text{m}^2\) (\(8\,000\,000\ \text{cm}^2\))។ នៅលើប្លង់មាត្រដ្ឋាន \(1/200\) តើផ្ទៃដីនោះមានទំហំប៉ុន្មានសង់ទីម៉ែត្រការេ?', NULL, '["\\(400\\ \\text{cm}^2\\)", "\\(4\\ \\text{cm}^2\\)", "\\(40\\ \\text{cm}^2\\)", "\\(200\\ \\text{cm}^2\\)"]', 3, NULL, 2, 'mcq', '\(S_{\text{ប្លង់}} = \dfrac{S_{\text{ពិត}}}{200^2} = \dfrac{8\,000\,000}{40\,000} = 200\ \text{cm}^2\)', 'មាត្រដ្ឋាន', 'medium', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9817, 'ចម្ងាយពិតពីរាជធានីភ្នំពេញទៅខេត្តសៀមរាបគឺ \(310\ \text{km}\)។ នៅលើផែនទីមាត្រដ្ឋាន \(1/1\,000\,000\) តើចម្ងាយនេះមានប្រវែងប៉ុន្មានសង់ទីម៉ែត្រ?', NULL, '["\\(310\\ \\text{cm}\\)", "\\(62\\ \\text{cm}\\)", "\\(3.1\\ \\text{cm}\\)", "\\(31\\ \\text{cm}\\)"]', 3, NULL, 2, 'mcq', '\(D = 31\,000\,000\ \text{cm} \Rightarrow d = \dfrac{31\,000\,000}{1\,000\,000} = 31\ \text{cm}\)', 'មាត្រដ្ឋាន', 'medium', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
