INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9818, 'ពហុកោណ \(A''B''C''D''\) ជារូបពង្រីកនៃពហុកោណ \(ABCD\)។ បើជ្រុង \(AB = 4\ \text{cm}\) រីឯជ្រុងត្រូវគ្នា \(A''B'' = 10\ 	ext{cm}\) តើមេគុណពង្រីក \(k\) ស្មើនឹងប៉ុន្មាន?', 'g8-2980f88d96.svg', '["\\(6\\)", "\\(0.4\\)", "\\(2.5\\)", "\\(2\\)"]', 2, NULL, 2, 'mcq', '\(k = \dfrac{A''B''}{AB} = \dfrac{10}{4} = 2.5\)', 'មាត្រដ្ឋាន', 'medium', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9819, 'នៅលើបន្ទាត់មាត្រដ្ឋាន គេកំណត់ថាប្រវែង \(1\ \text{cm}\) តំណាងឱ្យ \(25\ \text{km}\) ជាក់ស្តែង។ តើមាត្រដ្ឋានជាប្រភាគស្មើនឹងប៉ុន្មាន?', NULL, '["\\(\\dfrac{1}{250}\\)", "\\(\\dfrac{1}{250\\,000}\\)", "\\(\\dfrac{1}{2\\,500\\,000}\\)", "\\(\\dfrac{1}{25\\,000}\\)"]', 2, NULL, 2, 'mcq', '\(25\ \text{km} = 2\,500\,000\ \text{cm} \Rightarrow E = \dfrac{1}{2\,500\,000}\)', 'មាត្រដ្ឋាន', 'medium', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9820, 'នៅលើប្លង់ស្ថាបត្យកម្មមាត្រដ្ឋាន \(1/50\) ទ្វារផ្ទះមួយមានទទឹង \(1.8\ \text{cm}\)។ គណនាទទឹងពិតនៃទ្វារនោះជាម៉ែត្រ។', NULL, '["\\(9\\ \\text{m}\\)", "\\(0.75\\ \\text{m}\\)", "\\(0.9\\ \\text{m}\\)", "\\(1.8\\ \\text{m}\\)"]', 2, NULL, 2, 'mcq', '\(D = 1.8 \times 50 = 90\ \text{cm} = 0.9\ \text{m}\)', 'មាត្រដ្ឋាន', 'medium', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9821, 'អាងហែលទឹកមួយមានបណ្តោយពិត \(25\ \text{m}\) និងទទឹងពិត \(10\ \text{m}\)។ នៅលើប្លង់មាត្រដ្ឋាន \(1/250\) តើវិមាត្រទាំងពីរស្មើប៉ុន្មាន?', NULL, '["\\(25\\ \\text{cm} \\times 10\\ \\text{cm}\\)", "\\(10\\ \\text{cm} \\times 4\\ \\text{cm}\\)", "\\(1\\ \\text{cm} \\times 0.4\\ \\text{cm}\\)", "\\(5\\ \\text{cm} \\times 2\\ \\text{cm}\\)"]', 1, NULL, 2, 'mcq', '\(d_1 = \dfrac{2\,500}{250} = 10\ \text{cm}\), \(d_2 = \dfrac{1\,000}{250} = 4\ \text{cm}\)', 'មាត្រដ្ឋាន', 'medium', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9822, 'សួនច្បាររាងចតុកោណកែងមួយមានបរិមាត្រលើប្លង់ \(30\ \text{cm}\)។ បើប្លង់មានមាត្រដ្ឋាន \(1/400\) គណនាបរិមាត្រពិតនៃសួនគិតជាម៉ែត្រ។', NULL, '["\\(12\\ \\text{m}\\)", "\\(1\\,200\\ \\text{m}\\)", "\\(120\\ \\text{m}\\)", "\\(60\\ \\text{m}\\)"]', 2, NULL, 2, 'mcq', '\(P_{\text{ពិត}} = 30 \times 400 = 12\,000\ \text{cm} = 120\ \text{m}\)', 'មាត្រដ្ឋាន', 'medium', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9823, 'ចម្ងាយលើផែនទីមាត្រដ្ឋាន \(1/100\,000\) គឺ \(8\ \text{cm}\)។ បើគេគូរចម្ងាយដដែលនេះលើផែនទីថ្មីមាត្រដ្ឋាន \(1/50\,000\) តើវាមានប្រវែងប៉ុន្មាន?', NULL, '["\\(8\\ \\text{cm}\\)", "\\(32\\ \\text{cm}\\)", "\\(4\\ \\text{cm}\\)", "\\(16\\ \\text{cm}\\)"]', 3, NULL, 2, 'mcq', 'ចម្ងាយពិត \(8 \times 100\,000 = 800\,000\ \text{cm} \Rightarrow d_2 = \dfrac{800\,000}{50\,000} = 16\ \text{cm}\)', 'មាត្រដ្ឋាន', 'medium', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9824, 'រូបភាពកោសិកាមួយមើលតាមមីក្រូទស្សន៍មានប្រវែង \(15\ \text{mm}\)។ បើមីក្រូទស្សន៍ពង្រីកបានមាត្រដ្ឋាន \(500 : 1\) គណនាទំហំពិតនៃកោសិកា។', NULL, '["\\(0.3\\ \\text{mm}\\)", "\\(0.03\\ \\text{mm}\\)", "\\(30\\ \\text{mm}\\)", "\\(0.003\\ \\text{mm}\\)"]', 1, NULL, 2, 'mcq', '\(D = \dfrac{15}{500} = 0.03\ \text{mm}\)', 'មាត្រដ្ឋាន', 'medium', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9825, 'ប្លង់បន្ទប់រាងចតុកោណព្នាយកែងមួយមានមាត្រដ្ឋាន \(1/200\) ដោយបាតទាំងពីរលើប្លង់គឺ \(2.5\ \text{dm}\) និង \(3.75\ \text{dm}\) ហើយកម្ពស់ \(2\ \text{dm}\)។ គណនាមាឌខ្យល់ក្នុងបន្ទប់ បើកម្ពស់ពិតនៃបន្ទប់គឺ \(3.75\ \text{m}\)។', NULL, '["\\(18\\,750\\ \\text{m}^3\\)", "\\(9\\,375\\ \\text{m}^3\\)", "\\(2\\,500\\ \\text{m}^3\\)", "\\(4\\,687.5\\ \\text{m}^3\\)"]', 1, NULL, 3, 'mcq', 'វិមាត្រពិត ៖ បាតតូច \(50\ \text{m}\), បាតធំ \(75\ \text{m}\), កម្ពស់បាត \(40\ \text{m} \Rightarrow S = 2\,500\ \text{m}^2 \Rightarrow V = 2\,500 \times 3.75 = 9\,375\ \text{m}^3\)', 'មាត្រដ្ឋាន', 'hard', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9826, 'ពីបន្ទប់ក្នុងលំហាត់ខាងលើដែលមានផ្ទៃក្រឡាពិត \(2\,500\ \text{m}^2\) បើថ្លៃក្រាលការ៉ូគឺ \(1\,600\ \text{៛/m}^2\) គណនាប្រាក់ដែលត្រូវទិញការ៉ូ។', NULL, '["\\(5\\,000\\,000\\ \\text{៛}\\)", "\\(4\\,000\\,000\\ \\text{៛}\\)", "\\(3\\,200\\,000\\ \\text{៛}\\)", "\\(2\\,500\\,000\\ \\text{៛}\\)"]', 1, NULL, 3, 'mcq', '\(2\,500 \times 1\,600 = 4\,000\,000\ \text{៛}\)', 'មាត្រដ្ឋាន', 'hard', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9827, 'ចម្ងាយពិត \(310\ \text{km}\) តើលើផែនទីមាត្រដ្ឋាន \(1/80\,000\) ត្រូវតាងដោយប្រវែងប៉ុន្មាន?', NULL, '["\\(3.875\\ \\text{m}\\)", "\\(3.1\\ \\text{m}\\)", "\\(15.5\\ \\text{m}\\)", "\\(6.2\\ \\text{m}\\)"]', 0, NULL, 3, 'mcq', '\(d = \dfrac{31\,000\,000\ \text{cm}}{80\,000} = 387.5\ \text{cm} = 3.875\ \text{m}\)', 'មាត្រដ្ឋាន', 'hard', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9828, 'នៅលើប្លង់សុរិយោដីមាត្រដ្ឋាន \(1/5\,000\) ដីឡូត៍រាងចតុកោណកែងមួយមានបណ្តោយ \(8\ \text{cm}\) និងទទឹង \(5\ \text{cm}\)។ គណនាផ្ទៃដីពិតគិតជាហិកតា (\(\text{ha}\))។', NULL, '["\\(100\\ \\text{ha}\\)", "\\(1\\ \\text{ha}\\)", "\\(20\\ \\text{ha}\\)", "\\(10\\ \\text{ha}\\)"]', 3, NULL, 3, 'mcq', 'បណ្តោយពិត \(400\ \text{m}\), ទទឹងពិត \(250\ \text{m} \Rightarrow S = 100\,000\ \text{m}^2 = 10\ \text{ha}\)', 'មាត្រដ្ឋាន', 'hard', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9829, 'ពហុកោណពីរដូចគ្នាមានផលធៀបបរិមាត្រ \(\dfrac{P_1}{P_2} = \dfrac{3}{5}\)។ បើផ្ទៃក្រឡានៃពហុកោណទីមួយគឺ \(36\ \text{cm}^2\) គណនាផ្ទៃក្រឡានៃពហុកោណទីពីរ។', NULL, '["\\(100\\ \\text{cm}^2\\)", "\\(60\\ \\text{cm}^2\\)", "\\(120\\ \\text{cm}^2\\)", "\\(80\\ \\text{cm}^2\\)"]', 0, NULL, 3, 'mcq', '\(\dfrac{S_1}{S_2} = \left(\dfrac{3}{5}\right)^2 = \dfrac{9}{25} \Rightarrow S_2 = \dfrac{36 \times 25}{9} = 100\ \text{cm}^2\)', 'មាត្រដ្ឋាន', 'hard', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9830, 'នៅលើផែនទីមាត្រដ្ឋាន \(1/100\,000\) ភូមិបី \(A, B, C\) បង្កើតបានត្រីកោណកែងត្រង់ \(A\) ដែល \(AB = 3\ \text{cm}\) និង \(AC = 4\ \text{cm}\)។ គណនាចម្ងាយពិតត្រង់រវាងភូមិ \(B\) និង \(C\) គិតជាគីឡូម៉ែត្រ។', NULL, '["\\(2.5\\ \\text{km}\\)", "\\(7\\ \\text{km}\\)", "\\(50\\ \\text{km}\\)", "\\(5\\ \\text{km}\\)"]', 3, NULL, 3, 'mcq', '\(BC_{\text{ប្លង់}} = \sqrt{3^2 + 4^2} = 5\ \text{cm} \Rightarrow D = 5 \times 100\,000 = 500\,000\ \text{cm} = 5\ \text{km}\)', 'មាត្រដ្ឋាន', 'hard', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9831, 'គំរូយន្តហោះជ័រមួយផលិតឡើងតាមមាត្រដ្ឋានប្រវែង \(1 : 50\) នៃយន្តហោះពិត។ តើផលធៀបមាឌនៃគំរូធៀបនឹងមាឌយន្តហោះពិតស្មើនឹងប៉ុន្មាន?', NULL, '["\\(\\dfrac{1}{50}\\)", "\\(\\dfrac{1}{500\\,000}\\)", "\\(\\dfrac{1}{125\\,000}\\)", "\\(\\dfrac{1}{2\\,500}\\)"]', 2, NULL, 3, 'mcq', 'ផលធៀបមាឌស្មើគូបនៃមាត្រដ្ឋានប្រវែង ៖ \(E^3 = \left(\dfrac{1}{50}\right)^3 = \dfrac{1}{125\,000}\)', 'មាត្រដ្ឋាន', 'hard', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9832, 'រូបថតពីដ្រូន (Drone) មួយសន្លឹកមានមាត្រដ្ឋាន \(1 : 2\,000\)។ នៅលើរូបថត ស្រះទឹកមួយមានបណ្តោយ \(4.5\ \text{cm}\)។ គណនាប្រវែងពិតនៃស្រះនោះ។', NULL, '["\\(90\\ \\text{m}\\)", "\\(900\\ \\text{m}\\)", "\\(9\\ \\text{m}\\)", "\\(45\\ \\text{m}\\)"]', 0, NULL, 3, 'mcq', '\(D = 4.5 \times 2\,000 = 9\,000\ \text{cm} = 90\ \text{m}\)', 'មាត្រដ្ឋាន', 'pisa', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9833, 'តារាងបាល់ទាត់ស្តង់ដារមួយមានវិមាត្រពិត \(105\ \text{m} \times 68\ \text{m}\)។ បើវិស្វករគូសលើប្លង់មាត្រដ្ឋាន \(1 : 500\) តើវិមាត្រលើប្លង់ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(21\\ \\text{cm} \\times 13.6\\ \\text{cm}\\)", "\\(5.25\\ \\text{cm} \\times 3.4\\ \\text{cm}\\)", "\\(10.5\\ \\text{cm} \\times 6.8\\ \\text{cm}\\)", "\\(42\\ \\text{cm} \\times 27.2\\ \\text{cm}\\)"]', 0, NULL, 3, 'mcq', '\(d_1 = \dfrac{10\,500}{500} = 21\ \text{cm}\), \(d_2 = \dfrac{6\,800}{500} = 13.6\ \text{cm}\)', 'មាត្រដ្ឋាន', 'pisa', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9834, 'រថយន្តពិតមួយមានបណ្តោយ \(4.8\ \text{m}\)។ ក្រុមហ៊ុនផលិតរថយន្តក្មេងលេងផលិតតាមមាត្រដ្ឋាន \(1 : 24\) (Diecast)។ គណនាបណ្តោយរថយន្តក្មេងលេងនោះគិតជាសង់ទីម៉ែត្រ។', NULL, '["\\(12\\ \\text{cm}\\)", "\\(48\\ \\text{cm}\\)", "\\(24\\ \\text{cm}\\)", "\\(20\\ \\text{cm}\\)"]', 3, NULL, 3, 'mcq', '\(d = \dfrac{480\ \text{cm}}{24} = 20\ \text{cm}\)', 'មាត្រដ្ឋាន', 'pisa', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9835, 'នៅលើផែនទីមាត្រដ្ឋាន \(1 : 2\,000\,000\) ចម្ងាយផ្លូវជាតិពីភ្នំពេញទៅក្រុងព្រះសីហនុវាស់បាន \(11.5\ \text{cm}\)។ បើរថយន្តមួយស៊ីសាំង \(8\ \text{L}\) ក្នុង \(100\ \text{km}\) គណនាបរិមាណសាំងដែលត្រូវប្រើ។', NULL, '["\\(23\\ \\text{L}\\)", "\\(16\\ \\text{L}\\)", "\\(18.4\\ \\text{L}\\)", "\\(20.5\\ \\text{L}\\)"]', 2, NULL, 3, 'mcq', 'ចម្ងាយពិត ៖ \(11.5 \times 20 = 230\ \text{km} \Rightarrow \text{សាំង} = \dfrac{230 \times 8}{100} = 18.4\ \text{L}\)', 'មាត្រដ្ឋាន', 'pisa', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9836, 'នៅលើប្លង់ផ្ទះមាត្រដ្ឋាន \(1 : 50\) បន្ទប់ទទួលភ្ញៀវមានផ្ទៃ \(160\ \text{cm}^2\)។ បើថ្លៃលាបថ្នាំកម្រាលគឺ \(5\$/\text{m}^2\) គណនាថ្លៃលាបថ្នាំសរុប។', NULL, '["\\(160\\$\\)", "\\(400\\$\\)", "\\(200\\$\\)", "\\(100\\$\\)"]', 2, NULL, 3, 'mcq', '\(S_{\text{ពិត}} = 160 \times 50^2 = 160 \times 2\,500 = 400\,000\ \text{cm}^2 = 40\ \text{m}^2 \Rightarrow 40 \times 5 = 200\$\)', 'មាត្រដ្ឋាន', 'pisa', 1, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9837, 'នៅលើប្លង់សាលារៀនមួយមានមាត្រដ្ឋាន \(E = \dfrac{1}{200}\)។
ក. ពន្យល់អត្ថន័យនៃមាត្រដ្ឋាន \(1/200\)។
ខ. បើបន្ទប់រៀនមួយមានបណ្តោយលើប្លង់ \(4.5\ \text{cm}\) គណនាបណ្តោយពិតជាម៉ែត្រ។
គ. បើទទឹងពិតគឺ \(6\ \text{m}\) គណនាទទឹងលើប្លង់ជាសង់ទីម៉ែត្រ។', 'g8-b1a9362c1c.svg', '[]', 0, NULL, 5, 'writing', 'ក. មាត្រដ្ឋាន \(1/200\) មានន័យថា ប្រវែង \(1\ \text{cm}\) នៅលើប្លង់តំណាងឱ្យប្រវែងពិត \(200\ \text{cm} = 2\ \text{m}\) (1 ពិន្ទុ)
ខ. បណ្តោយពិត ៖ \(D = 4.5 \times 200 = 900\ \text{cm} = 9\ \text{m}\) (2 ពិន្ទុ)
គ. ទទឹងលើប្លង់ ៖ \(d = \dfrac{600\ \text{cm}}{200} = 3\ \text{cm}\) (2 ពិន្ទុ)', 'មាត្រដ្ឋាន', 'easy', 0, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9838, 'ចម្ងាយពិតជាក់ស្តែងរវាងទីប្រជុំជនពីរគឺ \(25\ \text{km}\)។ នៅលើផែនទីមួយ ចម្ងាយរវាងទីប្រជុំជនទាំងពីរវាស់បាន \(5\ \text{cm}\)។
ក. បំលែងចម្ងាយពិត \(25\ \text{km}\) ទៅជាសង់ទីម៉ែត្រ (\(\text{cm}\))។
ខ. សរសេររូបមន្ត និងគណនាមាត្រដ្ឋាន \(E\) នៃផែនទី។
គ. បើនៅលើផែនទីដដែល ចម្ងាយរវាងចំណុចពីរទៀតគឺ \(8\ \text{cm}\) គណនាចម្ងាយពិតជាគីឡូម៉ែត្រ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. បំលែង ៖ \(25\ \text{km} = 25 \times 100\,000 = 2\,500\,000\ \text{cm}\) (1 ពិន្ទុ)
ខ. មាត្រដ្ឋាន ៖ \(E = \dfrac{d}{D} = \dfrac{5}{2\,500\,000} = \dfrac{1}{500\,000}\) (2 ពិន្ទុ)
គ. ចម្ងាយពិត ៖ \(D = 8 \times 500\,000 = 4\,000\,000\ \text{cm} = 40\ \text{km}\) (2 ពិន្ទុ)', 'មាត្រដ្ឋាន', 'medium', 0, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9839, 'ប្លង់ផ្ទះមួយមានមាត្រដ្ឋាន \(1 : 100\)។ បន្ទប់គេងមួយជារាងចតុកោណកែងមានវិមាត្រលើប្លង់ ៖ បណ្តោយ \(4.5\ \text{cm}\) និងទទឹង \(3.6\ \text{cm}\)។
ក. គណនាបណ្តោយពិត និងទទឹងពិតនៃបន្ទប់គិតជាម៉ែត្រ។
ខ. គណនាផ្ទៃក្រឡាពិតនៃបន្ទប់ជាម៉ែត្រការេ (\(\text{m}^2\))។
គ. គណនាផ្ទៃក្រឡាលើប្លង់ រួចផ្ទៀងផ្ទាត់ផលធៀបផ្ទៃក្រឡាស្មើ \(E^2\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. បណ្តោយពិត ៖ \(4.5 \times 100 = 450\ \text{cm} = 4.5\ \text{m}\); ទទឹងពិត ៖ \(3.6 \times 100 = 360\ \text{cm} = 3.6\ \text{m}\) (2 ពិន្ទុ)
ខ. ផ្ទៃពិត ៖ \(S = 4.5 \times 3.6 = 16.2\ \text{m}^2\) (2 ពិន្ទុ)
គ. ផ្ទៃលើប្លង់ ៖ \(4.5 \times 3.6 = 16.2\ \text{cm}^2\)។ ផលធៀប ៖ \(\dfrac{16.2\ \text{cm}^2}{162\,000\ \text{cm}^2} = \dfrac{1}{10\,000} = \left(\dfrac{1}{100}\right)^2\) (ត្រឹមត្រូវ) (1 ពិន្ទុ)', 'មាត្រដ្ឋាន', 'medium', 0, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9840, 'ចម្ងាយរវាងរាជធានីភ្នំពេញ និងខេត្តសៀមរាបមានចម្ងាយពិត \(310\ \text{km}\)។
ក. បំលែង \(310\ \text{km}\) ទៅជាសង់ទីម៉ែត្រ។
ខ. គណនាប្រវែងដែលត្រូវគូសលើផែនទីមាត្រដ្ឋាន \(1/1\,000\,000\)។
គ. គណនាប្រវែងដែលត្រូវគូសលើផែនទីមាត្រដ្ឋាន \(1/500\,000\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(310\ \text{km} = 310 \times 100\,000 = 31\,000\,000\ \text{cm}\) (1 ពិន្ទុ)
ខ. មាត្រដ្ឋាន \(1/1\,000\,000\) ៖ \(d_1 = \dfrac{31\,000\,000}{1\,000\,000} = 31\ \text{cm}\) (2 ពិន្ទុ)
គ. មាត្រដ្ឋាន \(1/500\,000\) ៖ \(d_2 = \dfrac{31\,000\,000}{500\,000} = 62\ \text{cm}\) (2 ពិន្ទុ)', 'មាត្រដ្ឋាន', 'medium', 0, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9841, 'សួនច្បាររាងចតុកោណកែងមួយមានវិមាត្រលើប្លង់ ៖ បណ្តោយ \(6\ \text{cm}\) និងទទឹង \(3.5\ \text{cm}\) គូសតាមមាត្រដ្ឋាន \(1/250\)។
ក. គណនាបរិមាត្រលើប្លង់នៃសួនច្បារ។
ខ. គណនាបរិមាត្រពិតជាក់ស្តែងគិតជាម៉ែត្រ។
គ. គណនាផ្ទៃក្រឡាពិតជាក់ស្តែងនៃសួនច្បារគិតជាម៉ែត្រការេ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. បរិមាត្រលើប្លង់ ៖ \(P_{\text{ប្លង់}} = 2(6 + 3.5) = 2(9.5) = 19\ \text{cm}\) (1 ពិន្ទុ)
ខ. បរិមាត្រពិត ៖ \(P_{\text{ពិត}} = 19 \times 250 = 4\,750\ \text{cm} = 47.5\ \text{m}\) (2 ពិន្ទុ)
គ. វិមាត្រពិត ៖ \(6 \times 2.5 = 15\ \text{m}\) និង \(3.5 \times 2.5 = 8.75\ \text{m} \Rightarrow S = 15 \times 8.75 = 131.25\ \text{m}^2\) (2 ពិន្ទុ)', 'មាត្រដ្ឋាន', 'medium', 0, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9842, 'ប្លង់បន្ទប់មួយមានមាត្រដ្ឋាន \(1/200\) មានរាងជាចតុកោណព្នាយកែងដែលមានវិមាត្រលើប្លង់ ៖ បាតតូច \(2.5\ \text{dm}\), បាតធំ \(3.75\ \text{dm}\) និងកម្ពស់បាត \(2\ \text{dm}\)។
ក. គណនាវិមាត្រពិតទាំងបីគិតជាម៉ែត្រ។
ខ. គណនាផ្ទៃក្រឡាបាតបន្ទប់ពិតប្រាកដ។
គ. រកមាឌខ្យល់ក្នុងបន្ទប់បើកម្ពស់ពិដានពិតគឺ \(3.75\ \text{m}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. បាតតូចពិត ៖ \(2.5 \times 200 = 500\ \text{dm} = 50\ \text{m}\); បាតធំពិត ៖ \(3.75 \times 200 = 750\ \text{dm} = 75\ \text{m}\); កម្ពស់ពិត ៖ \(2 \times 200 = 400\ \text{dm} = 40\ \text{m}\) (2 ពិន្ទុ)
ខ. ផ្ទៃបាតពិត ៖ \(S = \dfrac{(50 + 75) \times 40}{2} = 62.5 \times 40 = 2\,500\ \text{m}^2\) (2 ពិន្ទុ)
គ. មាឌខ្យល់ ៖ \(V = S \times H = 2\,500 \times 3.75 = 9\,375\ \text{m}^3\) (1 ពិន្ទុ)', 'មាត្រដ្ឋាន', 'hard', 0, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9843, 'ចម្ងាយពិតរវាងទីក្រុងពីរគឺ \(310\ \text{km}\) (\(31\,000\,000\ \text{cm}\))។
ក. គណនាប្រវែងលើផែនទីមាត្រដ្ឋាន \(1/50\,000\)។
ខ. គណនាប្រវែងលើផែនទីមាត្រដ្ឋាន \(1/100\,000\)។
គ. ប្រៀបធៀបលទ្ធផលទាំងពីរ និងពន្យល់ថាតើហេតុអ្វីបានជាមាត្រដ្ឋាន \(1/100\,000\) សមរម្យជាងសម្រាប់គូសលើក្រដាសផ្ទាំងធំ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. មាត្រដ្ឋាន \(1/50\,000\) ៖ \(d_1 = \dfrac{31\,000\,000}{50\,000} = 620\ \text{cm} = 6.2\ \text{m}\) (2 ពិន្ទុ)
ខ. មាត្រដ្ឋាន \(1/100\,000\) ៖ \(d_2 = \dfrac{31\,000\,000}{100\,000} = 310\ \text{cm} = 3.1\ \text{m}\) (2 ពិន្ទុ)
គ. ប្រវែង \(3.1\ \text{m}\) តូចជាងពាក់កណ្តាលនៃ \(6.2\ \text{m}\) ដែលងាយស្រួលគូស និងបោះពុម្ពជាផ្ទាំងផែនទីផ្លូវថ្នល់ (1 ពិន្ទុ)', 'មាត្រដ្ឋាន', 'hard', 0, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9844, 'គេមានពហុកោណពីរ \(P_1\) និង \(P_2\) ដែលដូចគ្នា។ ជ្រុងត្រូវគ្នាមួយគូមានប្រវែង \(9.1\ \text{mm}\) និង \(6.4\ \text{mm}\)។
ក. គណនាផលធៀបដូច \(k = \dfrac{6.4}{9.1}\) (យកទសភាគ ២ ខ្ទង់)។
ខ. បើជ្រុងមួយទៀតនៃពហុកោណទីមួយមានប្រវែង \(25.1\ \text{mm}\) គណនាប្រវែងជ្រុងត្រូវគ្នានៃពហុកោណទីពីរ។
គ. បើផ្ទៃក្រឡាពហុកោណទីមួយគឺ \(200\ \text{mm}^2\) គណនាផ្ទៃក្រឡាពហុកោណទីពីរ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផលធៀបដូច ៖ \(k = \dfrac{6.4}{9.1} pprox 0.70\) (1 ពិន្ទុ)
ខ. ជ្រុងត្រូវគ្នា ៖ \(25.1 \times 0.70 pprox 17.6\ \text{mm}\) (2 ពិន្ទុ)
គ. ផលធៀបផ្ទៃក្រឡាគឺ \(k^2 pprox 0.70^2 = 0.49 \Rightarrow S_2 = 200 \times 0.49 = 98\ \text{mm}^2\) (2 ពិន្ទុ)', 'មាត្រដ្ឋាន', 'hard', 0, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9845, 'នៅលើប្លង់មាត្រដ្ឋាន \(1/500\) ដីឡូត៍រាងត្រីកោណកែងមួយមានជ្រុងមុំកែង \(6\ \text{cm}\) និង \(8\ \text{cm}\)។
ក. គណនាប្រវែងអ៊ីប៉ូតេនុសលើប្លង់។
ខ. គណនាប្រវែងជ្រុងពិតទាំងបីគិតជាម៉ែត្រ។
គ. គណនាផ្ទៃក្រឡាដីពិតជាក់ស្តែងគិតជាម៉ែត្រការេ (\(\text{m}^2\))។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. អ៊ីប៉ូតេនុសលើប្លង់ ៖ \(c = \sqrt{6^2 + 8^2} = 10\ \text{cm}\) (1 ពិន្ទុ)
ខ. ជ្រុងពិត ៖ \(6 \times 5 = 30\ \text{m}\), \(8 \times 5 = 40\ \text{m}\), \(10 \times 5 = 50\ \text{m}\) (2 ពិន្ទុ)
គ. ផ្ទៃដីពិត ៖ \(S = \dfrac{30 \times 40}{2} = 600\ \text{m}^2\) (2 ពិន្ទុ)', 'មាត្រដ្ឋាន', 'hard', 0, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9846, 'ពហុកីឡដ្ឋានជាតិមួយមានទីលានបាល់ទាត់បណ្តោយពិត \(100\ \text{m}\) និងទទឹងពិត \(64\ \text{m}\)។
ក. វិស្វករចង់គូសប្លង់ទីលាននេះឱ្យល្មមនៅលើក្រដាស \(A4\) (ទំហំ \(30\ \text{cm} \times 21\ \text{cm}\))។ បើគាត់ជ្រើសរើសមាត្រដ្ឋាន \(1 : 500\) គណនាវិមាត្រលើប្លង់។
ខ. តើប្លង់នេះសមស្របនឹងទំហំក្រដាស \(A4\) ដែរឬទេ? ពន្យល់។
គ. គណនាផ្ទៃក្រឡាទីលានពិតជាក់ស្តែងជាម៉ែត្រការេ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. បណ្តោយលើប្លង់ ៖ \(\dfrac{10\,000}{500} = 20\ \text{cm}\); ទទឹងលើប្លង់ ៖ \(\dfrac{6\,400}{500} = 12.8\ \text{cm}\) (2 ពិន្ទុ)
ខ. សមស្រប ព្រោះ \(20\ \text{cm} < 30\ \text{cm}\) និង \(12.8\ \text{cm} < 21\ \text{cm}\) (ប្លង់ដាក់ចូលក្នុងក្រដាស A4 បានយ៉ាងស្អាត) (2 ពិន្ទុ)
គ. ផ្ទៃទីលានពិត ៖ \(100 \times 64 = 6\,400\ \text{m}^2\) (1 ពិន្ទុ)', 'មាត្រដ្ឋាន', 'pisa', 0, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9847, 'ប្លង់សាលប្រជុំរាងចតុកោណកែងមួយមានមាត្រដ្ឋាន \(1 : 200\) មានវិមាត្រលើប្លង់ \(12\ \text{cm} \times 8\ \text{cm}\)។
ក. គណនាវិមាត្រពិតនៃសាលប្រជុំគិតជាម៉ែត្រ។
ខ. គណនាផ្ទៃក្រឡាពិតនៃសាលប្រជុំ។
គ. បើគេក្រាលការ៉ូដែលមានតម្លៃ \(1\,500\ \text{៛/m}^2\) រួមទាំងថ្លៃឈ្នួលជាង \(2\,500\ \text{៛/m}^2\) គណនាថវិកាសរុបដែលត្រូវចំណាយ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. បណ្តោយពិត ៖ \(12 \times 2 = 24\ \text{m}\); ទទឹងពិត ៖ \(8 \times 2 = 16\ \text{m}\) (2 ពិន្ទុ)
ខ. ផ្ទៃពិត ៖ \(S = 24 \times 16 = 384\ \text{m}^2\) (1 ពិន្ទុ)
គ. ថ្លៃសរុបក្នុង ១ ម៉ែត្រការេ ៖ \(1\,500 + 2\,500 = 4\,000\ \text{៛}\) នាំឱ្យថវិកាសរុប ៖ \(384 \times 4\,000 = 1\,536\,000\ \text{៛}\) (2 ពិន្ទុ)', 'មាត្រដ្ឋាន', 'pisa', 0, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9848, 'សិស្សម្នាក់បើកមើលផែនទីឌីជីថល (Google Maps) នៅលើទូរស័ព្ទ។ នៅលើអេក្រង់មានមាត្រដ្ឋានជាបន្ទាត់បង្ហាញថាប្រវែង \(1.5\ \text{cm}\) ស្មើ \(3\ \text{km}\)។
ក. គណនាមាត្រដ្ឋានជាប្រភាគនៃផែនទីនោះ។
ខ. បើគាត់វាស់ចម្ងាយផ្លូវពីផ្ទះទៅសាលារៀនឃើញ \(4.5\ \text{cm}\) គណនាចម្ងាយពិតជាគីឡូម៉ែត្រ។
គ. បើគាត់ជិះកង់ដោយល្បឿនមធ្យម \(18\ \text{km/h}\) តើគាត់ចំណាយពេលប៉ុន្មាននាទីដើម្បីទៅដល់សាលា?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(3\ \text{km} = 300\,000\ \text{cm} \Rightarrow E = \dfrac{1.5}{300\,000} = \dfrac{1}{200\,000}\) (2 ពិន្ទុ)
ខ. ចម្ងាយពិត ៖ \(4.5 \times 2 = 9\ \text{km}\) (1 ពិន្ទុ)
គ. រយៈពេលធ្វើដំណើរ ៖ \(T = \dfrac{9}{18} = 0.5\ \text{ម៉ោង} = 30\ \text{នាទី}\) (2 ពិន្ទុ)', 'មាត្រដ្ឋាន', 'pisa', 0, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9849, 'នៅលើប្លង់សុរិយោដីមាត្រដ្ឋាន \(1 : 2\,500\) ស្រែមួយរាងចតុកោណព្នាយមានបាតតូច \(4\ \text{cm}\), បាតធំ \(8\ \text{cm}\) និងកម្ពស់ \(3\ \text{cm}\)។
ក. គណនាវិមាត្រពិតទាំងបីគិតជាម៉ែត្រ។
ខ. គណនាផ្ទៃក្រឡាដីស្រែពិតជាក់ស្តែងគិតជាហិកតា (\(\text{ha}\))។
គ. បើទិន្នផលស្រូវទទួលបាន \(4\ \text{តោន/ហិកតា}\) គណនាបរិមាណស្រូវប្រមូលផលបានសរុប។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. បាតតូចពិត \(4 \times 25 = 100\ \text{m}\); បាតធំពិត \(8 \times 25 = 200\ \text{m}\); កម្ពស់ពិត \(3 \times 25 = 75\ \text{m}\) (2 ពិន្ទុ)
ខ. ផ្ទៃស្រែ ៖ \(S = \dfrac{(100 + 200) \times 75}{2} = 150 \times 75 = 11\,250\ \text{m}^2 = 1.125\ \text{ha}\) (2 ពិន្ទុ)
គ. ផលស្រូវសរុប ៖ \(1.125 \times 4 = 4.5\ \text{តោន}\) (1 ពិន្ទុ)', 'មាត្រដ្ឋាន', 'pisa', 0, '8', 'មាត្រដ្ឋាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9850, 'គំរូរថយន្តក្រុងមួយត្រូវបានផលិតតាមមាត្រដ្ឋាន \(1 : 40\)។ នៅលើគំរូនោះ បណ្តោយមានប្រវែង \(30\ \text{cm}\), ទទឹង \(6.25\ \text{cm}\) និងកម្ពស់ \(8\ \text{cm}\)។
ក. គណនាវិមាត្រពិតទាំងបីនៃរថយន្តក្រុងគិតជាម៉ែត្រ។
ខ. គណនាមាឌពិតនៃរថយន្តក្រុងគិតជាម៉ែត្រគូប (\(\text{m}^3\))។
គ. បង្ហាញថាផលធៀបមាឌរវាងគំរូនិងរថយន្តពិតស្មើនឹង \(\left(\dfrac{1}{40}\right)^3\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. បណ្តោយពិត ៖ \(30 \times 40 = 1\,200\ \text{cm} = 12\ \text{m}\); ទទឹងពិត ៖ \(6.25 \times 40 = 250\ \text{cm} = 2.5\ \text{m}\); កម្ពស់ពិត ៖ \(8 \times 40 = 320\ \text{cm} = 3.2\ \text{m}\) (2 ពិន្ទុ)
ខ. មាឌពិត ៖ \(V_{\text{ពិត}} = 12 \times 2.5 \times 3.2 = 96\ \text{m}^3\) (2 ពិន្ទុ)
គ. មាឌគំរូ ៖ \(30 \times 6.25 \times 8 = 1\,500\ \text{cm}^3 = 0.0015\ \text{m}^3\)។ ផលធៀប ៖ \(\dfrac{0.0015}{96} = \dfrac{1}{64\,000} = \left(\dfrac{1}{40}\right)^3\) (ត្រឹមត្រូវ) (1 ពិន្ទុ)', 'មាត្រដ្ឋាន', 'pisa', 0, '8', 'មាត្រដ្ឋាន', NULL, 0);
